{"new_string":"export function debounce(fn, ms) {
  let timer;
  let lastArgs;

  const invoke = () => {
    const args = lastArgs;
    timer = undefined;
    lastArgs = undefined;
    return fn(...args);
  };

  const debounced = (...args) => {
    clearTimeout(timer);
    lastArgs = args;
    timer = setTimeout(invoke, ms);
  };

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = undefined;
    lastArgs = undefined;
  };

  debounced.flush = () => {
    if (timer !== undefined) {
      clearTimeout(timer);
      return invoke();
    }
  };

  return debounced;
}
