test('waits for a quiet interval and uses the last arguments', (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const debounced = debounce((...args) => calls.push(args), 10);

  debounced('first');
  t.mock.timers.tick(5);
  debounced('last', 2);
  t.mock.timers.tick(9);
  assert.deepEqual(calls, []);
  t.mock.timers.tick(1);
  assert.deepEqual(calls, [['last', 2]]);
  debounced.flush();
  t.mock.timers.tick(10);
  assert.deepEqual(calls, [['last', 2]]);
});

test('cancel drops the pending call and allows reuse', (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const debounced = debounce((...args) => calls.push(args), 10);

  debounced.cancel();
  debounced('discard');
  debounced.cancel();
  debounced.cancel();
  debounced.flush();
  t.mock.timers.tick(10);
  assert.deepEqual(calls, []);

  debounced();
  t.mock.timers.tick(10);
  assert.deepEqual(calls, [[]]);
});

test('flush runs the latest pending call immediately and only once', (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const debounced = debounce((...args) => calls.push(args), 10);

  debounced.flush();
  assert.deepEqual(calls, []);
  debounced('first');
  debounced('last');
  debounced.flush();
  assert.deepEqual(calls, [['last']]);
  debounced.flush();
  t.mock.timers.tick(10);
  assert.deepEqual(calls, [['last']]);

  debounced('again');
  t.mock.timers.tick(10);
  assert.deepEqual(calls, [['last'], ['again']]);
});

test('a callback can schedule a new pending call', (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const debounced = debounce((value) => {
    calls.push(value);
    if (value === 'first') debounced('second');
  }, 10);

  debounced('first');
  debounced.flush();
  assert.deepEqual(calls, ['first']);
  debounced.flush();
  assert.deepEqual(calls, ['first', 'second']);
  t.mock.timers.tick(10);
  assert.deepEqual(calls, ['first', 'second']);
});
